// 1. Get the raw text from Claude
let rawText = $input.first().json.content[0].text;

// 2. Clean out any Markdown formatting Claude might have added
let cleanText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

// 3. Convert it to a real JSON object safely
try {
  const parsedData = JSON.parse(cleanText);
  return [{ json: parsedData }];
} catch (error) {
  // If it STILL fails, send a safe fallback so the frontend doesn't crash
  return [{ 
    json: { 
      status: "ambiguous", 
      question: "I encountered a formatting error. Could you please rephrase your situation?" 
    } 
  }];
}
